(()=>{
  const ROOT=document.getElementById("adventureRoot"),VIEW=document.getElementById("adventureView"),STORE="international-math-adventure-v1",FLAGS="international-math-adventure-flags-v1";
  const $=id=>document.getElementById(id),clone=value=>JSON.parse(JSON.stringify(value));
  const freshState=()=>({started:false,screen:"landing",location:"earth",human:{hp:5,shield:0},ship:{hp:20,shield:20,brokenUntil:0},shipParts:0,placedParts:[],shipBuilt:false,used:[],correctBank:0,missions:{moonTravel:false,moonPrep:false,moonBoss:false,marsTravel:false,marsSurvey:false},boss:{destroyed:[],canTarget:false,currentId:""},inventory:[],mascots:[],materials:[],mission:null,lastHp:Date.now(),lastShield:Date.now()});
  let state;try{state={...freshState(),...(JSON.parse(localStorage.getItem(STORE)||"null")||{})}}catch{state=freshState()}
  state.human={hp:5,shield:0,...state.human};state.ship={hp:20,shield:20,brokenUntil:0,...state.ship};state.missions={...freshState().missions,...state.missions};state.boss={destroyed:[],canTarget:false,currentId:"",...state.boss};
  let flags;try{flags=JSON.parse(localStorage.getItem(FLAGS)||"[]")||[]}catch{flags=[]}
  let introTimer=null,selectedPiece=null,mapScale=1,mapX=0,mapY=0,dragStart=null,resumeScreen=state.screen&&state.screen!=="landing"?state.screen:"map";
  const save=()=>localStorage.setItem(STORE,JSON.stringify(state));
  const saveFlags=()=>localStorage.setItem(FLAGS,JSON.stringify(flags));
  const esc=value=>String(value??"").replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
  function questionPool(){const result=[];Object.entries(papers).forEach(([paperId,list])=>(list||[]).forEach(q=>{if(q&&q.ready!==false&&q.en&&q.answer!==undefined)result.push({...q,_id:`${paperId}:${q.n}`,_paper:paperNames[paperId]||paperId})}));return result}
  const getQuestion=id=>questionPool().find(q=>q._id===id);
  function pickQuestion(){const pool=questionPool(),available=pool.filter(q=>!state.used.includes(q._id));return available[Math.floor(Math.random()*available.length)]||null}
  function normalize(value){return String(value??"").toLowerCase().replace(/\s+/g,"").replace(/,/g,"")}
  function accepted(q,value){return [q.answer,...(q.accepted||[])].map(normalize).includes(normalize(value))}
  function applyRegen(){const now=Date.now();if(state.ship.brokenUntil&&now>=state.ship.brokenUntil){state.ship={hp:20,shield:20,brokenUntil:0}}
    const shieldTicks=Math.floor((now-state.lastShield)/10000),hpTicks=Math.floor((now-state.lastHp)/20000);if(shieldTicks>0){state.human.shield=Math.min(5,state.human.shield+shieldTicks);if(!state.ship.brokenUntil)state.ship.shield=Math.min(20,state.ship.shield+shieldTicks);state.lastShield+=shieldTicks*10000}if(hpTicks>0){state.human.hp=Math.min(5,state.human.hp+hpTicks);if(!state.ship.brokenUntil)state.ship.hp=Math.min(20,state.ship.hp+hpTicks);state.lastHp+=hpTicks*20000}save();updateHud()}
  function updateHud(){if(!$(`humanHealth`))return;$(`humanHealth`).textContent=`♥ ${state.human.hp}/5`;$(`humanShield`).textContent=`◆ ${state.human.shield}/5`;$(`shipHealth`).textContent=`♥ ${state.ship.hp}/20`;$(`shipShield`).textContent=`◆ ${state.ship.shield}/20`}
  function showAdventure(){ROOT.hidden=false;document.body.classList.add("adventure-active");$("adventureHud").hidden=state.screen==="landing";render()}
  function showLegacy(target="practice"){ROOT.hidden=true;document.body.classList.remove("adventure-active");location.hash=target;$("adventureMenu").hidden=true}
  function openMenu(){$("adventureMenu").hidden=false;$(`adventureMenuButton`).setAttribute("aria-expanded","true")}
  function closeMenu(){$("adventureMenu").hidden=true;$(`adventureMenuButton`).setAttribute("aria-expanded","false")}
  function render(){applyRegen();clearTimeout(introTimer);$("adventureHud").hidden=state.screen==="landing";if(state.screen==="landing")renderLanding();else if(state.screen==="map")renderMap();else if(state.screen==="brief")renderBrief();else if(state.screen==="shipyard")renderShipyard();else if(state.screen==="mission")renderMission();else if(state.screen==="bossIntro")renderBossIntro();else if(state.screen==="boss")renderBoss();else if(state.screen==="reward")renderReward();updateHud()}
  function renderLanding(){const continuing=state.started;VIEW.innerHTML=`<section class="adventure-landing"><div class="landing-orbits" aria-hidden="true"><i></i><i></i><i></i></div><div class="landing-copy"><p class="adventure-kicker">INTERNATIONAL MATH · SOLAR QUEST</p><h1>START FROM <span>EARTH</span></h1><p>Build your spaceship, solve maths missions and rescue friends across the Solar System.</p><button class="start-adventure-button" id="startAdventure" type="button">${continuing?"Continue adventure":"Start adventure"} →</button>${continuing?`<small class="continue-note">Progress saved on this device · Current location: ${esc(state.location)}</small>`:""}</div></section>`;$("startAdventure").onclick=()=>{state.started=true;state.screen=continuing?resumeScreen:"map";save();render()}}
  function renderMap(){state.screen="map";save();const broken=Math.max(0,state.ship.brokenUntil-Date.now()),repair=broken?`${Math.ceil(broken/60000)} min repair`:"Ready";VIEW.innerHTML=`<section class="solar-map-screen"><div class="map-toolbar"><div><p class="adventure-kicker">YOUR SOLAR SYSTEM</p><h1>Choose the next destination</h1><p>${state.shipBuilt?`Spaceship: ${repair}`:`Collect ${10-state.shipParts} more ship part${10-state.shipParts===1?"":"s"} on Earth.`}</p></div><div class="map-controls"><button id="zoomOutMap" aria-label="Zoom out">−</button><button id="resetMap" aria-label="Reset map">⌾</button><button id="zoomInMap" aria-label="Zoom in">+</button></div></div><div class="solar-viewport" id="solarViewport"><div class="solar-canvas" id="solarCanvas"><i class="map-route route-moon"></i><i class="map-route route-mars"></i><button class="planet-node earth" data-place="earth"><span>🌍</span><small>Earth</small></button><button class="planet-node moon${state.shipBuilt?"":" locked"}" data-place="moon"><span>🌕</span><small>Moon</small></button><button class="planet-node mars${state.shipBuilt?"":" locked"}" data-place="mars"><span>🔴</span><small>Mars</small></button><button class="planet-node jupiter locked" data-place="locked"><span>🟤</span><small>Jupiter<br>Coming soon</small></button><button class="planet-node saturn locked" data-place="locked"><span>🪐</span><small>Saturn<br>Coming soon</small></button><button class="planet-node wormhole locked" data-place="wormhole"><span>🌀</span><small>Other worlds<br>Coming soon</small></button>${state.shipBuilt?`<img class="ship-map-token" src="assets/adventure-ship-v1.png" alt="Your spaceship">`:""}${state.shipBuilt?`<button class="map-event comet" data-place="comet">☄ Comet event · 3</button><button class="map-event ore" data-place="ore">◆ Space mine · 5</button>`:""}</div></div></section>`;setupMapControls();document.querySelectorAll("[data-place]").forEach(button=>button.onclick=()=>selectPlace(button.dataset.place))}
  function setupMapControls(){const canvas=$("solarCanvas"),viewport=$("solarViewport");const draw=()=>canvas.style.transform=`translate(${mapX}px,${mapY}px) scale(${mapScale})`;$("zoomInMap").onclick=()=>{mapScale=Math.min(2.2,mapScale+.2);draw()};$("zoomOutMap").onclick=()=>{mapScale=Math.max(.75,mapScale-.2);draw()};$("resetMap").onclick=()=>{mapScale=1;mapX=mapY=0;draw()};viewport.onpointerdown=e=>{if(e.target.closest("button"))return;dragStart={x:e.clientX-mapX,y:e.clientY-mapY};viewport.setPointerCapture(e.pointerId)};viewport.onpointermove=e=>{if(!dragStart)return;mapX=e.clientX-dragStart.x;mapY=e.clientY-dragStart.y;draw()};viewport.onpointerup=()=>dragStart=null}
  function selectPlace(place){if(place==="locked"||place==="wormhole")return notify("This world is coming in a future upgrade.");if(place==="earth"){if(state.shipParts<10)return setBrief("earthParts");if(!state.shipBuilt){state.screen="shipyard";save();return render()}return setBrief("earthReady")}if(!state.shipBuilt)return notify("Build your spaceship on Earth first.");if(state.ship.brokenUntil>Date.now())return notify("The spaceship is being repaired. Try again when the repair timer ends.");if(place==="moon")return setBrief(state.missions.moonTravel?state.missions.moonPrep?state.missions.moonBoss?"moonComplete":"moonBoss":"moonPrep":"moonTravel");if(place==="mars")return setBrief(state.missions.marsTravel?state.missions.marsSurvey?"marsComplete":"marsSurvey":"marsTravel");if(place==="comet")return setBrief("comet");if(place==="ore")return setBrief("ore")}
  function setBrief(kind){state.screen="brief";state.brief=kind;save();render()}
  const briefing={earthParts:{title:"Build the Earth Explorer",desc:"Answer 10 different questions. Every correct answer unlocks one spaceship piece.",questions:"10",reward:"10 ship parts",danger:"Explorer HP"},earthReady:{title:"Earth Base",desc:"Your spaceship is ready. Choose another destination on the Solar System map.",questions:"Complete",reward:"Explorer ship",danger:"Safe zone"},moonTravel:{title:"Launch to the Moon",desc:"Complete five flight questions. Enemy ships or a meteor storm may appear on the route.",questions:"5",reward:"Moon access",danger:"Ship HP + Shield"},moonPrep:{title:"Infiltrate the Moon Base",desc:"Answer 10 questions to charge your weapons and open the robot arena.",questions:"10",reward:"Energy weapons",danger:"Explorer HP"},moonBoss:{title:"Defeat the Moon Robot",desc:"Answer correctly, then choose a body part to attack. Destroy both arms and legs before targeting the head.",questions:"5 hits",reward:"Rescue 1 mascot",danger:"Boss counterattack"},moonComplete:{title:"Moon rescued",desc:"The Moon base is safe and your rescued friend has joined the collection.",questions:"Complete",reward:"Moon Explorer set",danger:"Safe"},marsTravel:{title:"Launch to Mars",desc:"Complete five new flight questions to reach the red planet.",questions:"5",reward:"Mars access",danger:"Ship HP + Shield"},marsSurvey:{title:"Explore Mars",desc:"Complete 25 different questions to survey the planet and unlock the pilot reward.",questions:"25",reward:"Mars sticker",danger:"Explorer HP"},marsComplete:{title:"Mars survey complete",desc:"The first Mars expedition is complete. A full Mars boss will arrive in a later upgrade.",questions:"Complete",reward:"Mars Pioneer",danger:"Safe"},comet:{title:"Intercept a comet",desc:"Answer three questions before the comet passes. Win an upgrade for your spaceship.",questions:"3",reward:"Ship upgrade",danger:"Ship HP + Shield"},ore:{title:"Mine a space asteroid",desc:"Answer five questions to recover one material not already in your collection.",questions:"5",reward:"Element or gem",danger:"Explorer HP"}};
  function renderBrief(){const b=briefing[state.brief]||briefing.earthReady,complete=/Complete|rescued|complete/i.test(b.questions+b.title),travel=/Travel|comet/.test(state.brief),energy=travel?`Ship ${state.ship.hp} HP · ${state.ship.shield} Shield`:`Explorer ${state.human.hp} HP · ${state.human.shield} Shield`;VIEW.innerHTML=`<section class="mission-brief"><article class="mission-brief-card"><p class="adventure-kicker">MISSION BRIEFING</p><h1>${b.title}</h1><p>${b.desc}</p><div class="brief-grid"><article><small>Challenge</small><strong>${b.questions}</strong></article><article><small>Reward</small><strong>${b.reward}</strong></article><article><small>Risk</small><strong>${b.danger}</strong></article><article><small>Current energy</small><strong>${energy}</strong></article><article><small>Question pool</small><strong>No repeats</strong></article></div><div class="guide-box"><strong>How to play</strong><br>Answer in English. Hint or Translate costs 1 Shield; if Shield is empty, it costs 1 HP. Every correct answer restores 1 Shield. Every third correct answer restores 1 HP.</div><div class="mission-actions"><button class="secondary-space-button" id="briefBack">← Solar map</button>${complete?"":`<button class="primary-space-button" id="launchMission">Launch mission →</button>`}</div></article></section>`;$("briefBack").onclick=()=>{state.screen="map";save();render()};if($("launchMission"))$("launchMission").onclick=launchBriefMission}
  function launchBriefMission(){const kind=state.brief;if(kind==="earthReady"||kind.endsWith("Complete")){state.screen="map";return render()}if(kind==="moonBoss"){state.screen="bossIntro";state.boss.currentId="";save();return render()}const totals={earthParts:10,moonTravel:5,moonPrep:10,marsTravel:5,marsSurvey:25,comet:3,ore:5};startMission(kind,totals[kind])}
  function startMission(kind,total){const travel=/Travel|comet/.test(kind);state.mission={kind,total,done:0,currentId:"",travel,notice:""};if(travel&&Math.random()<.5){const loss=Math.floor(Math.random()*5)+1;state.ship.shield=Math.max(0,state.ship.shield-loss);state.mission.notice=`Meteor storm! The ship lost ${loss} Shield.`}state.screen="mission";save();nextMissionQuestion()}
  function nextMissionQuestion(){const q=pickQuestion();if(!q)return notify("The available question pool has been completed. Reset questions from the menu to continue.");state.mission.currentId=q._id;state.mission.checked=false;state.mission.correct=false;state.mission.feedback="";save();renderMission()}
  function pieceStyle(index){const col=index%5,row=Math.floor(index/5);return `background-position:${col*25}% ${row*100}%`}
  function renderShipyard(){VIEW.innerHTML=`<section class="shipyard-screen"><article class="shipyard-card"><div class="shipyard-layout"><div><p class="adventure-kicker">EARTH SHIPYARD</p><h1>Assemble your spaceship</h1><p>Drag every unlocked piece into the matching numbered slot. On touch screens, tap a piece and then tap its slot.</p><div class="parts-tray">${Array.from({length:10},(_,i)=>`<button class="ship-piece${state.placedParts.includes(i)?" placed":""}" draggable="true" data-piece="${i}" aria-label="Spaceship piece ${i+1}" style="${pieceStyle(i)}"></button>`).join("")}</div><p id="shipyardStatus">${state.placedParts.length}/10 pieces assembled</p><div class="ship-progress"><i style="--progress:${state.placedParts.length*10}%"></i></div></div><div><div class="assembly-board">${Array.from({length:10},(_,i)=>`<button class="ship-slot${state.placedParts.includes(i)?" filled":""}" data-slot="${i}" aria-label="Slot ${i+1}" style="${pieceStyle(i)}"></button>`).join("")}</div><div class="mission-actions" style="margin-top:20px"><button class="secondary-space-button" id="shipyardBack">← Solar map</button><button class="primary-space-button" id="finishShip" ${state.placedParts.length<10?"disabled":""}>Activate spaceship →</button></div></div></div></article></section>`;setupShipyard()}
  function setupShipyard(){document.querySelectorAll("[data-piece]").forEach(piece=>{piece.ondragstart=e=>e.dataTransfer.setData("text/plain",piece.dataset.piece);piece.onclick=()=>{selectedPiece=Number(piece.dataset.piece);$("shipyardStatus").textContent=`Piece ${selectedPiece+1} selected. Choose slot ${selectedPiece+1}.`}});document.querySelectorAll("[data-slot]").forEach(slot=>{slot.ondragover=e=>e.preventDefault();slot.ondrop=e=>{e.preventDefault();placePiece(Number(e.dataTransfer.getData("text/plain")),Number(slot.dataset.slot))};slot.onclick=()=>{if(selectedPiece!==null)placePiece(selectedPiece,Number(slot.dataset.slot))}});$("shipyardBack").onclick=()=>{state.screen="map";save();render()};$("finishShip").onclick=()=>{state.shipBuilt=true;state.inventory.push("Earth Explorer spaceship");state.screen="map";save();render()}}
  function placePiece(piece,slot){if(piece!==slot){$("shipyardStatus").textContent="That piece does not fit here. Try its matching slot.";return}if(!state.placedParts.includes(piece))state.placedParts.push(piece);selectedPiece=null;save();renderShipyard()}
  function missionName(kind){return ({earthParts:"Earth ship parts",moonTravel:"Flight to Moon",moonPrep:"Moon weapon charge",marsTravel:"Flight to Mars",marsSurvey:"Mars survey",comet:"Comet interception",ore:"Space mining"})[kind]||"Mission"}
  function renderMission(){const m=state.mission,q=getQuestion(m.currentId)||pickQuestion();if(!q){state.screen="map";return render()}const waiting=(!m.travel&&state.human.hp<1)||(m.travel&&state.ship.hp<1);VIEW.innerHTML=`<section class="mission-screen"><article class="mission-card"><div class="mission-question"><p class="adventure-kicker">${missionName(m.kind)} · ${m.done+1}/${m.total}</p><h1>${esc(q.title||q.skill||"Math mission")}</h1><p class="mission-question-text">${esc(q.en)}</p>${q.image?`<img src="${esc(q.image)}" alt="Question diagram">`:""}<div class="mission-answer"><input id="missionAnswer" aria-label="Answer" autocomplete="off" ${waiting||m.checked?"disabled":""}><button id="missionCheck" type="button" ${waiting||m.checked?"disabled":""}>Check</button></div><p class="mission-feedback ${m.correct?"good":m.feedback?"bad":""}" id="missionFeedback">${waiting?"Energy empty. Wait until at least 1 HP is restored.":esc(m.feedback||"")}</p><div class="mission-tool-row"><button id="missionHint" type="button" ${m.checked?"disabled":""}>Hint −1 Shield</button><button id="missionTranslate" type="button" ${m.checked?"disabled":""}>Translate −1 Shield</button><button id="missionFlag" type="button">${flags.includes(q._id)?"⚑ Flagged":"⚑ Flag question"}</button>${m.checked&&m.correct?`<button id="missionNext" type="button">Continue →</button>`:""}</div><div id="missionHelp"></div>${m.checked&&m.correct?`<div class="guide-box"><strong>Solution</strong><br>${(q.steps||[q.answer]).map(esc).join("<br>")}</div>`:""}</div><aside class="mission-sidebar"><h3>Mission status</h3>${m.notice?`<p class="mission-feedback bad">${esc(m.notice)}</p>`:""}<div class="mission-progress-dots">${Array.from({length:m.total},(_,i)=>`<i class="${i<m.done?"done":""}"></i>`).join("")}</div>${m.travel?`<div class="battle-visual"><span class="enemy-ship">🛸</span>${m.correct?`<i class="laser-shot"></i>`:""}</div><p>One correct answer destroys one enemy ship.</p>`:`<p>Correct answers restore Shield. Every third correct answer restores HP.</p>`}<button class="secondary-space-button" id="leaveMission">Pause mission</button></aside></article></section>`;bindMission(q)}
  function bindMission(q){$("missionCheck").onclick=()=>checkMissionAnswer(q);$("missionAnswer").onkeydown=e=>{if(e.key==="Enter")checkMissionAnswer(q)};$("missionHint").onclick=()=>useHelp(q,"hint");$("missionTranslate").onclick=()=>useHelp(q,"translate");$("missionFlag").onclick=()=>toggleFlag(q);$("leaveMission").onclick=()=>{state.screen="map";save();render()};if($("missionNext"))$("missionNext").onclick=advanceMission}
  function activeStats(){return state.mission?.travel?state.ship:state.human}
  function spendDefense(amount=1){const stats=activeStats();while(amount-->0){if(stats.shield>0)stats.shield--;else stats.hp=Math.max(0,stats.hp-1)}save();updateHud()}
  function useHelp(q,type){spendDefense(1);const box=$("missionHelp");box.className="guide-box";box.innerHTML=type==="hint"?`<strong>Hint</strong><br>${esc(q.hint||"Look for the important numbers and work one step at a time.")}`:`<strong>Vietnamese</strong><br>${esc(q.vi||"Bản dịch đang được bổ sung.")}`;renderMissionIfDead()}
  function renderMissionIfDead(){const stats=activeStats();if(stats.hp<1){state.mission.feedback="Energy empty. Wait for recovery.";save();renderMission()}}
  function healForCorrect(){const stats=activeStats();stats.shield=Math.min(state.mission?.travel?20:5,stats.shield+1);state.correctBank=(state.correctBank||0)+1;if(state.correctBank>=3){state.human.hp=Math.min(5,state.human.hp+1);state.correctBank=0}}
  function damageForWrong(){if(state.mission.travel){if(state.ship.shield>=2)state.ship.shield-=2;else if(state.ship.shield===1){state.ship.shield=0;state.ship.hp=Math.max(0,state.ship.hp-1)}else state.ship.hp=Math.max(0,state.ship.hp-1);if(state.ship.hp===0)breakShip()}else spendDefense(1)}
  function breakShip(){state.ship.brokenUntil=Date.now()+15*60*1000;state.ship.shield=0;state.mission=null;state.location=state.location||"earth";state.screen="map";notify("Spaceship disabled. You returned to the last planet. Full repair takes 15 minutes.")}
  function checkMissionAnswer(q){if(state.mission.checked)return;const good=accepted(q,$("missionAnswer").value);state.mission.checked=good;state.mission.correct=good;if(good){state.mission.feedback="Correct! Shield restored.";state.used.push(q._id);healForCorrect()}else{state.mission.feedback="Incorrect. Energy lost — choose another answer.";damageForWrong()}save();if(state.screen==="map")render();else renderMission()}
  function advanceMission(){const m=state.mission;m.done++;if(m.kind==="earthParts")state.shipParts=Math.min(10,state.shipParts+1);if(m.done>=m.total)return completeMission(m.kind);nextMissionQuestion()}
  function completeMission(kind){state.mission=null;if(kind==="earthParts"){state.shipParts=10;state.screen="shipyard"}else if(kind==="moonTravel"){state.missions.moonTravel=true;state.location="moon";state.screen="brief";state.brief="moonPrep"}else if(kind==="moonPrep"){state.missions.moonPrep=true;state.inventory.push("Energy blaster","Energy blade");state.screen="brief";state.brief="moonBoss"}else if(kind==="marsTravel"){state.missions.marsTravel=true;state.location="mars";state.screen="brief";state.brief="marsSurvey"}else if(kind==="marsSurvey"){state.missions.marsSurvey=true;state.inventory.push("Mars Pioneer sticker");showReward("Mars survey complete","🔴","Mars Pioneer sticker unlocked.")}else if(kind==="comet"){state.inventory.push("Comet engine upgrade");showReward("Comet intercepted","☄️","Your spaceship received a Comet engine upgrade.")}else if(kind==="ore"){const choices=["Fe","Al","Cu","Zn","Mg","Ca","C","O","N","S","Si","H₂O","CO₂","NaCl","Diamond","Emerald","Topaz","Sapphire","Amethyst"],next=choices.find(item=>!state.materials.includes(item))||choices[Math.floor(Math.random()*choices.length)];state.materials.push(next);showReward("Material recovered","◆",`${next} added to your collection. Five different materials can power a future wormhole.`)}save();render()}
  function showReward(title,icon,message){state.screen="reward";state.reward={title,icon,message};save()}
  function renderReward(){const r=state.reward||{title:"Mission complete",icon:"★",message:"Reward unlocked."};VIEW.innerHTML=`<section class="reward-screen"><article class="reward-card"><p class="adventure-kicker">MISSION COMPLETE</p><div style="font-size:100px">${r.icon}</div><h1>${esc(r.title)}</h1><p>${esc(r.message)}</p><div class="reward-grid"><span>🛰 ${state.inventory.length} items</span><span>🐾 ${state.mascots.length} rescued</span><span>◆ ${new Set(state.materials).size} materials</span><span>★ ${state.used.length} questions</span></div><button class="primary-space-button" id="rewardMap">Return to Solar System</button></article></section>`;$("rewardMap").onclick=()=>{state.screen="map";save();render()}}
  function renderBossIntro(){VIEW.innerHTML=`<section class="boss-intro"><button class="skip-intro" id="skipIntro">Skip intro</button><img src="assets/space-robot-boss-v1.png" alt="Moon robot boss"><div class="fight-call">LET'S FIGHT!</div></section>`;$("skipIntro").onclick=startBoss;introTimer=setTimeout(startBoss,10000)}
  function startBoss(){clearTimeout(introTimer);state.screen="boss";state.boss.destroyed=[];state.boss.canTarget=false;state.boss.currentId="";save();nextBossQuestion()}
  function nextBossQuestion(){const q=pickQuestion();if(!q)return notify("Reset questions to continue the boss battle.");state.boss.currentId=q._id;state.boss.canTarget=false;state.boss.feedback="";save();renderBoss()}
  function renderBoss(){const q=getQuestion(state.boss.currentId)||pickQuestion(),parts=["left-arm","right-arm","left-leg","right-leg","head"],limbsGone=parts.slice(0,4).every(p=>state.boss.destroyed.includes(p)),waiting=state.human.hp<1;VIEW.innerHTML=`<section class="boss-screen"><article class="boss-card"><p class="adventure-kicker">MOON BOSS · ${state.boss.destroyed.length}/5 HITS</p><div class="boss-health"><i style="--hp:${(5-state.boss.destroyed.length)*20}%"></i></div><div class="boss-layout"><div class="boss-arena"><img src="assets/space-robot-boss-v1.png" alt="Moon robot boss"><div class="boss-targets">${parts.map(part=>`<button class="boss-target target-${part}${state.boss.destroyed.includes(part)?" destroyed":""}" data-target="${part}" ${(state.boss.destroyed.includes(part)||!state.boss.canTarget||(part==="head"&&!limbsGone))?"disabled":""}>${part==="head"?"◎":"×"}</button>`).join("")}</div></div><div class="boss-question-panel"><h2>${esc(q.en)}</h2><p>Answer correctly to unlock one attack. Destroy both arms and legs before the head.</p><div class="mission-answer"><input id="bossAnswer" aria-label="Boss answer" ${state.boss.canTarget||waiting?"disabled":""}><button id="bossCheck" ${state.boss.canTarget||waiting?"disabled":""}>Check</button></div><p class="mission-feedback ${state.boss.feedback?.startsWith("Correct")?"good":state.boss.feedback?"bad":""}">${waiting?"Wait until at least 1 HP is restored.":esc(state.boss.feedback||"")}</p><div class="mission-tool-row"><button id="bossHint">Hint −1 Shield</button><button id="bossTranslate">Translate −1 Shield</button><button id="bossFlag">${flags.includes(q._id)?"⚑ Flagged":"⚑ Flag question"}</button></div><div id="bossHelp"></div></div></div></article></section>`;bindBoss(q)}
  function bindBoss(q){$("bossCheck").onclick=()=>checkBoss(q);$("bossAnswer").onkeydown=e=>{if(e.key==="Enter")checkBoss(q)};$("bossHint").onclick=()=>bossHelp(q,"hint");$("bossTranslate").onclick=()=>bossHelp(q,"translate");$("bossFlag").onclick=()=>toggleFlag(q,true);document.querySelectorAll("[data-target]").forEach(button=>button.onclick=()=>attackBoss(button.dataset.target))}
  function bossHelp(q,type){const oldMission=state.mission;state.mission={travel:false};spendDefense(1);state.mission=oldMission;$("bossHelp").className="guide-box";$("bossHelp").innerHTML=type==="hint"?esc(q.hint||"Work one step at a time."):esc(q.vi||"Bản dịch đang được bổ sung.");if(state.human.hp<1)restartBossAfterDefeat()}
  function checkBoss(q){if(state.boss.canTarget)return;const good=accepted(q,$("bossAnswer").value);if(good){state.boss.canTarget=true;state.boss.feedback="Correct! Choose a target.";state.used.push(q._id);const oldMission=state.mission;state.mission={travel:false};healForCorrect();state.mission=oldMission}else{if(state.human.shield>=2)state.human.shield-=2;else if(state.human.shield===1){state.human.shield=0;state.human.hp=Math.max(0,state.human.hp-1)}else state.human.hp=Math.max(0,state.human.hp-1);state.boss.feedback="Wrong — the robot counterattacked.";if(state.human.hp<1)return restartBossAfterDefeat()}save();renderBoss()}
  function restartBossAfterDefeat(){state.boss={destroyed:[],canTarget:false,currentId:"",feedback:"Boss battle restarted. Wait for 1 HP."};save();nextBossQuestion()}
  function attackBoss(part){if(!state.boss.canTarget)return;state.boss.destroyed.push(part);state.boss.canTarget=false;if(state.boss.destroyed.length>=5)return winBoss();save();nextBossQuestion()}
  function winBoss(){state.missions.moonBoss=true;state.location="moon";const mascotIds=["pip","luna","finn","bao","leo","ellie","pebble","tiko"],available=mascotIds.filter(id=>!state.mascots.includes(id)),mascot=available[Math.floor(Math.random()*available.length)]||mascotIds[0];state.mascots.push(mascot);state.inventory.push("Moon Explorer sticker","Lunar paint","Energy blaster","Energy blade");state.reward={title:"Moon robot defeated",icon:`<span class="mascot-sprite mascot-${mascot} reward-mascot"></span>`,message:"A new friend is safe. Their special gift is coming soon."};state.screen="reward";save();render()}
  function toggleFlag(q,boss=false){const index=flags.indexOf(q._id);if(index>=0)flags.splice(index,1);else flags.push(q._id);saveFlags();boss?renderBoss():renderMission()}
  function exportFlags(){const rows=flags.map(id=>{const q=getQuestion(id);return q?{id,paper:q._paper,question:q.n,title:q.title,text:q.en}: {id}}),blob=new Blob([JSON.stringify(rows,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="international-math-adventure-flags.json";link.click();URL.revokeObjectURL(url)}
  function notify(message){window.alert(message)}
  function resetQuestions(){if(!confirm("Reset question history? Adventure progress, flags, items and rescued mascots will be kept."))return;state.used=[];state.mission=null;state.screen="map";save();closeMenu();render()}
  function resetAdventure(){if(!confirm("Reset the entire adventure? Spaceship, missions, items and rescued mascots will be erased. Question flags will be kept."))return;state=freshState();save();closeMenu();render()}
  $("adventureMenuButton").onclick=openMenu;$("adventureMenuClose").onclick=closeMenu;$("menuExplore").onclick=()=>{closeMenu();state.screen="map";save();render()};$("menuPractice").onclick=()=>showLegacy("practice");$("menuTest").onclick=()=>{showLegacy("practice");setTimeout(()=>$("testModeButton").click(),50)};$("menuExportFlags").onclick=exportFlags;$("resetQuestions").onclick=resetQuestions;$("resetAdventure").onclick=resetAdventure;$("adventureHome").onclick=()=>{state.screen="map";save();render()};$("returnAdventureButton").onclick=showAdventure;
  state.screen="landing";setInterval(()=>{const before=JSON.stringify([state.human,state.ship]);applyRegen();if(before!==JSON.stringify([state.human,state.ship])&&(state.screen==="mission"||state.screen==="boss"))render()},1000);showAdventure();
})();
